    tests=(LOCAL/'tests-final.log').read_text();counts=[int(x)for x in re.findall(r'test result: ok\. (\d+) passed',tests)]
    receipt=dict(research_branch='research/font04-document-fonts',contract_commit='06f24b122e1cd1cd879880166b8240c7e75747ed',product_baseline='c10e3dff93ca12ac410c0f6626a4ef74ce34e0c1',implementation_commits=['1ab7f832802a943f67ff12213c2182747d1bcd32','62d63e2f4710e6ce147f44e90d6f7eb38a369d8c'],scope_proposal=dict(branch='research/research-scope-proposal',commit='480a281e780d28827e9ee8bd950fd0fb71a41da1',pr='https://github.com/mitchins/scanweave/pull/25',state='draft, unmerged, documentation only'),font03=dict(commit='7ebc09ec7ec19d9c4ff260da621fcfbb021d909d',pr='https://github.com/mitchins/scanweave/pull/24',decision='Keep draft/unmerged pending independent acceptance and refreshed live Sonar.'),product_change_branch=None,merged_in_launch=[],B2_started=False,P2_generated_rendered_inspected=False,P2_preregistration_sha256=sha(ROOT/'p2-preregistration.json'),tests=dict(passed=sum(counts),groups=counts,failed=0,log=str(LOCAL/'tests-final.log'),sha256=sha(LOCAL/'tests-final.log')))
